import unittest
from solution import encode_records


class Probe(unittest.TestCase):
    def test_non_json_values_rejected(self):
        for value in ((1, 2), {1: 'x'}):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    encode_records([{'x': value}])


if __name__ == '__main__':
    unittest.main()

prompt.text:
The complete `solution.py` below should encode records as compact JSON while preserving every dictionary's insertion order, including nested dictionaries. `records` must be a list whose elements are dictionaries with string keys; otherwise raise `TypeError`. Values must be standard JSON values, and non-finite floats or unsupported values must raise `ValueError`. The input must not be mutated. Empty input must produce `"[]"`.

The source has exactly one semantic bug. Return a corrected complete source file without changing `encode_records`.

```python
import json


def encode_records(records):
    if not isinstance(records, list):
        raise TypeError("records must be a list")
    if any(not isinstance(record, dict) for record in records):
        raise TypeError("each record must be a dictionary")
    if any(any(not isinstance(key, str) for key in record) for record in records):
        raise TypeError("record keys must be strings")
    try:
        return json.dumps(records, separators=(",", ":"), sort_keys=True,
                          allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise ValueError("records contain a non-JSON value") from exc
```

